mapper.select:
SELECT c.id, c.post_id, c.user_id, c.body, c.created_at, u.username AS author_username, u.display_name AS author_display_name, u.avatar_key AS author_avatar_key FROM comments c JOIN users u ON u.id = c.user_id WHERE c.post_id = #{postId} AND c.deleted_at IS NULL
AND (c.created_at, c.id) > (#{cursorCreatedAt}, #{cursorId})
ORDER BY c.created_at ASC, c.id ASC LIMIT #{limit}
